import React, { FC } from 'react';
import { brand } from '@gitroom/helpers/brand/brand.config';

/**
 * The Manassa (منصة) symbol: the paper plane from the official logo on a
 * white rounded tile. Generated by var/brand/process_logo.py.
 */
export const BrandMark: FC<{ size?: number; className?: string }> = ({
  size = 32,
  className,
}) => {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={brand.assets.logo}
      width={size}
      height={size}
      alt=""
      aria-hidden="true"
      draggable={false}
      className={className}
      style={{ borderRadius: size * 0.22 }}
    />
  );
};
